SELECT 
FROM ${tableName}
WHERE store_name = #{storeName}
  AND namespace = #{namespace}
  AND task_id = #{taskId}

SELECT 
FROM ${tableName}
WHERE store_name = #{storeName}
  AND scan_bucket = #{scanBucket}
  AND (
        (status IN ('READY', 'RETRY_WAIT', 'WAIT_RECONCILE') AND next_execute_at <= #{now})
        OR (status = 'RUNNING' AND lease_until <= #{now})
  )
ORDER BY COALESCE(next_execute_at, lease_until), created_at
LIMIT #{limit}

