UPDATE ${tableName}
SET status = #{targetStatus},
    next_execute_at = #{nextExecuteAt,jdbcType=TIMESTAMP},
    owner_id = NULL,
    lease_until = NULL,
    version = version + 1,
    last_error_code = #{errorCode,jdbcType=VARCHAR},
